public partial class TextEdit
{
    // Compare defines a total ordering by comparing fields in declaration order (generate.mts compareStructures).
    public int Compare(TextEdit other)
    {
        var c0 = Range.Compare(other.Range);
        if (c0 != 0)
        {
            return c0;
        }
        return string.CompareOrdinal(NewText, other.NewText);
    }
}

