public partial class Range
{
    // Compare defines a total ordering by comparing fields in declaration order (generate.mts compareStructures).
    public int Compare(Range other)
    {
        var c0 = Start.Compare(other.Start);
        if (c0 != 0)
        {
            return c0;
        }
        return End.Compare(other.End);
    }
}

